"""Database access for SQLite (the default) and PostgreSQL.

Every query in the project is written once with ? placeholders. For
PostgreSQL they are turned into %s before the query runs, so the rest of
the code never needs to know which database it is talking to.
"""

import json
import re
import sqlite3
from datetime import datetime, timezone

from app.config import DATABASE_URL, DEFAULT_SETTINGS, PROJECT_DIR

SCHEMA_FILE = PROJECT_DIR / "database" / "schema.sql"

ID_TYPES = {
    "sqlite": "INTEGER PRIMARY KEY",
    "postgres": "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
}


def now() -> str:
    """Current time as ISO 8601 text, e.g. 2026-11-13T06:15:00+00:00."""
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _dict_row(cursor, row):
    return {col[0]: value for col, value in zip(cursor.description, row)}


class Database:
    """One open connection. Use it in a `with` block so it commits and closes."""

    def __init__(self, url: str | None = None):
        self.url = url or DATABASE_URL
        self.is_postgres = self.url.startswith(("postgres://", "postgresql://"))
        if self.is_postgres:
            import psycopg
            from psycopg.rows import dict_row

            self.conn = psycopg.connect(self.url, row_factory=dict_row)
        else:
            path = self.url.removeprefix("sqlite:///")
            self.conn = sqlite3.connect(path, timeout=30, check_same_thread=False)
            self.conn.row_factory = _dict_row
            self.conn.execute("PRAGMA journal_mode=WAL")  # readers don't block the crawler
            self.conn.execute("PRAGMA synchronous=NORMAL")

    # ---- running queries ----

    def _sql(self, sql: str) -> str:
        return sql.replace("?", "%s") if self.is_postgres else sql

    def execute(self, sql: str, params=()):
        return self.conn.execute(self._sql(sql), params)

    def executemany(self, sql: str, rows) -> None:
        cur = self.conn.cursor()
        cur.executemany(self._sql(sql), rows)
        cur.close()

    def all(self, sql: str, params=()) -> list[dict]:
        return self.execute(sql, params).fetchall()

    def one(self, sql: str, params=()) -> dict | None:
        return self.execute(sql, params).fetchone()

    def value(self, sql: str, params=()):
        """First column of the first row, or None."""
        row = self.one(sql, params)
        return next(iter(row.values())) if row else None

    def commit(self) -> None:
        self.conn.commit()

    def rollback(self) -> None:
        self.conn.rollback()

    def close(self) -> None:
        self.conn.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, *_):
        if exc_type:
            self.rollback()
        else:
            self.commit()
        self.close()

    # ---- settings (stored as JSON text) ----

    def get_setting(self, key: str, default=None):
        row = self.one("SELECT value FROM settings WHERE key = ?", (key,))
        return json.loads(row["value"]) if row else default

    def set_setting(self, key: str, value) -> None:
        self.execute(
            "INSERT INTO settings (key, value) VALUES (?, ?) "
            "ON CONFLICT (key) DO UPDATE SET value = excluded.value",
            (key, json.dumps(value)),
        )

    def crawl_settings(self) -> dict:
        return {key: self.get_setting(key, default) for key, default in DEFAULT_SETTINGS.items()}


def init_db(url: str | None = None) -> None:
    """Create any missing tables. Safe to run every time the app starts."""
    with Database(url) as db:
        schema = SCHEMA_FILE.read_text(encoding="utf-8")
        schema = re.sub(r"--[^\n]*", "", schema)  # drop comments
        schema = schema.replace("ID_PRIMARY_KEY", ID_TYPES["postgres" if db.is_postgres else "sqlite"])
        for statement in schema.split(";"):
            if statement.strip():
                db.execute(statement)
        for key, value in DEFAULT_SETTINGS.items():
            db.execute(
                "INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT (key) DO NOTHING",
                (key, json.dumps(value)),
            )
